"""Credit-hold sweep migrated from Meridian CRM 4.2 CRMScript."""

from decimal import Decimal, InvalidOperation
from fractions import Fraction
from typing import Any


def _numeric(value: Any) -> Fraction:
    """Apply legacy NVL(value, 0) numeric coercion without binary floats."""
    if value is None or value == "":
        return Fraction(0)

    try:
        if isinstance(value, Decimal):
            decimal_value = value
        elif isinstance(value, float):
            decimal_value = Decimal(str(value))
        else:
            decimal_value = Decimal(value)
    except (InvalidOperation, TypeError, ValueError) as exc:
        raise ValueError(f"Invalid legacy numeric value: {value!r}") from exc

    if not decimal_value.is_finite():
        raise ValueError(f"Invalid legacy numeric value: {value!r}")

    return Fraction(decimal_value)


def sweep(
    accounts: list[dict],
    orders: list[dict],
) -> tuple[list[dict], list]:
    """
    Apply the nightly credit-hold sweep.

    Returned account dictionaries preserve input order, while processing and
    audit emission follow ascending ACCT_ID primary-key order.
    """
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    eligible_indexes = [
        index
        for index, account in enumerate(new_accounts)
        if account.get("DEL_FLG", "") != "Y"
        and account.get("ACCT_TYP", "") == "C"
    ]
    eligible_indexes.sort(
        key=lambda index: new_accounts[index].get("ACCT_ID", "")
    )

    ordered_orders = sorted(
        enumerate(orders),
        key=lambda item: item[1].get("ORD_ID", ""),
    )

    for index in eligible_indexes:
        account = new_accounts[index]
        account_id = account.get("ACCT_ID", "")
        exposure = Fraction(0)

        for _, order in ordered_orders:
            if (
                order.get("ACCT_ID", "") == account_id
                and order.get("DEL_FLG", "") != "Y"
                and order.get("STAT_CD", "") == "I"
            ):
                exposure += _numeric(order.get("TOT_AMT", ""))

        credit_limit = _numeric(account.get("CRED_LIMIT", ""))

        if exposure > credit_limit and account.get("CRED_HOLD", "") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", account_id))

        if (
            exposure * 10 <= credit_limit * 8
            and account.get("CRED_HOLD", "") == "Y"
        ):
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", account_id))

    return new_accounts, audits
